var EASINGS={
  linear:function(t){return t;},
  easeInQuad:function(t){return t*t;},
  easeOutQuad:function(t){return t*(2-t);},
  easeInOutQuad:function(t){return t<0.5?2*t*t:-1+(4-2*t)*t;},
  easeInCubic:function(t){return t*t*t;},
  easeOutCubic:function(t){return (--t)*t*t+1;},
  easeInOutCubic:function(t){return t<0.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;},
  easeInSine:function(t){return 1-Math.cos(t*Math.PI/2);},
  easeOutSine:function(t){return Math.sin(t*Math.PI/2);},
  easeInOutSine:function(t){return -(Math.cos(Math.PI*t)-1)/2;}
};
function easingFn(name,t){ var f=EASINGS[name]; if(!f) return t; return f(t); }
function bezier(x1,y1,x2,y2,t){
  if(x1===y1 && x2===y2) return t;
  function A(a,b){return 1-3*b+3*a;} function B(a,b){return 3*b-6*a;} function C(a){return 3*a;}
  function calc(t,a,b){return ((A(a,b)*t+B(a,b))*t+C(a))*t;}
  function slope(t,a,b){return 3*A(a,b)*t*t+2*B(a,b)*t+C(a);}
  function tForX(x){ var t=x; for(var i=0;i<8;i++){ var xs=calc(t,x1,x2)-x; var d=slope(t,x1,x2); if(Math.abs(d)<1e-6)break; t-=xs/d; } return t; }
  return calc(tForX(t),y1,y2);
}
if (typeof module !== 'undefined' && module.exports) { module.exports = { easingFn:easingFn, bezier:bezier, EASINGS:EASINGS }; }
if (typeof window !== 'undefined') { window.EasingForgePure = { easingFn:easingFn, bezier:bezier, EASINGS:EASINGS }; }
